INSERT INTO `portal_images` (`id`, `nombre`, `clave`, `imagen`, `descripcion`, `activo`, `orden`, `created_at`, `updated_at`) VALUES (1,'Explora destinos y experiencias memorables','home_hero_1','portal/01KYTP25TGNG12QAFKRNPBF4VD.jpeg','Vinos de altura, cultura chapaca, naturaleza y caminos que conectan las seis provincias de Tarija.',1,1,'2026-07-10 01:08:43','2026-07-30 23:34:26');
INSERT INTO `portal_images` (`id`, `nombre`, `clave`, `imagen`, `descripcion`, `activo`, `orden`, `created_at`, `updated_at`) VALUES (2,'Escápate hacia paisajes inolvidables','home_hero_2','portal/01KX4BJXB8000S4S2ANJV00Z8G.jpeg','Descubre aguas cristalinas, cielos abiertos y experiencias perfectas para desconectarte y volver a sentir la naturaleza.',1,2,'2026-07-10 01:08:43','2026-07-18 04:36:18');
