INSERT INTO `provincias_turisticas` (`id`, `nombre`, `slug`, `provincia`, `subtitulo`, `resumen`, `descripcion`, `imagen`, `imagenes_secundarias`, `municipios`, `atractivos`, `fiestas`, `recomendaciones`, `orden`, `activo`, `created_at`, `updated_at`) VALUES (7,'Tarija','tarija','Cercado','Capital cultural de Tarija: San Roque, centro historico, miradores, mercados y vida chapaca.','Cercado concentra la ciudad de Tarija y varios de sus principales atractivos urbanos, culturales y gastronomicos.','La provincia Cercado es el punto de entrada natural para descubrir Tarija. Su capital combina plazas, mercados, patrimonio arquitectonico, miradores y una vida urbana tranquila que conserva identidad chapaca.\n\nUno de sus momentos mas representativos es la Fiesta Grande de San Roque, celebrada desde agosto, con los chunchos promesantes recorriendo la ciudad. Esta expresion fue inscrita por la UNESCO como Patrimonio Cultural Inmaterial de la Humanidad en 2021.\n\nEl recorrido turistico puede incluir la Casa Dorada, la Catedral Metropolitana de San Bernardo, el Mercado Central, el Parque Bolivar, la Iglesia de San Roque, el Museo Paleontologico y paseos urbanos como miradores y plazas.','municipios/01KY0KJMA01QDA5BHQGK7MPR87.jpg','[\"municipios/galeria/01KY0KJMC1P39D2VN8AXV1CD26.jpg\", \"municipios/galeria/01KY0KJMC7A0PGN0PFQQQC4H8A.JPG\", \"municipios/galeria/01KY0KJMCBH7ZKAP1D5QRKRVWG.jpg\", \"municipios/galeria/01KY0KJMCTAZGY4Z0QEMTENDR1.jpg\", \"municipios/galeria/01KY0KJMDBM7YSA6BHR5E47NK4.jpg\"]',NULL,'Casa Dorada y Casa de la Cultura\nCatedral Metropolitana de San Bernardo\nIglesia de San Roque\nMercado Central de Tarija\nParque Bolivar\nMuseo Nacional Paleontologico y Arqueologico\nMirador de los Suenos y miradores urbanos','Fiesta Grande de San Roque y chunchos promesantes\nEntrada de Comadres\nCarnaval Chapaco\nAbril en Tarija\nGastronomia tradicional en mercados y barrios historicos','Visitar el centro historico a pie por la manana\nReservar tiempo para el Mercado Central y la gastronomia local\nConsultar fechas de San Roque entre agosto y septiembre\nCombinar Cercado con rutas cercanas hacia San Lorenzo o Uriondo',1,1,'2026-07-21 00:19:35','2026-07-21 00:30:45');
INSERT INTO `provincias_turisticas` (`id`, `nombre`, `slug`, `provincia`, `subtitulo`, `resumen`, `descripcion`, `imagen`, `imagenes_secundarias`, `municipios`, `atractivos`, `fiestas`, `recomendaciones`, `orden`, `activo`, `created_at`, `updated_at`) VALUES (8,'Uriondo','uriondo','José María Avilés','Valles, vino, altura y la Ruta del Vino en Uriondo.','Provincia clave para experiencias vitivinicolas y paisajes altoandinos.','Jose Maria Aviles reune el valle de Uriondo, bodegas, vinedos, singani y paisajes de altura hacia Yunchara. Es una provincia ideal para turismo gastronomico, fotografico y de naturaleza.','municipios/01KY0KS9S5CK7NHJFDWDY0JE7P.jpg','[\"municipios/galeria/01KY0KS9SP5ZA1XQVN2PJXHGA5.JPG\", \"municipios/galeria/01KY0KS9SVKNZTGKTKNFXMV70P.JPG\", \"municipios/galeria/01KY0KS9T4YK99CF0Y1XJX6409.JPG\", \"municipios/galeria/01KY0KS9TBE5E7559NE9WH219W.jpg\", \"municipios/galeria/01KY0KS9TNABEHTKXRZWMS8S82.jpg\", \"municipios/galeria/01KY0KS9TW8B69HZDZ6PSE29WF.JPG\", \"municipios/galeria/01KY0KS9V20HCX5S0PGRKWT1BB.jpg\"]',NULL,'Ruta del Vino\nValle de la Concepcion\nBodegas y vinedos\nPaisajes altoandinos\nLagunas y rutas naturales','Vendimia chapaca\nExperiencias de degustacion\nFerias productivas locales','Coordinar visitas a bodegas con anticipacion\nLlevar abrigo para zonas altas\nCombinar gastronomia local con recorridos fotograficos',2,1,'2026-07-21 00:19:35','2026-07-21 00:34:23');
INSERT INTO `provincias_turisticas` (`id`, `nombre`, `slug`, `provincia`, `subtitulo`, `resumen`, `descripcion`, `imagen`, `imagenes_secundarias`, `municipios`, `atractivos`, `fiestas`, `recomendaciones`, `orden`, `activo`, `created_at`, `updated_at`) VALUES (9,'Yunchará','yunchara','José María Avilés','Valles, vino, altura y la Ruta del Vino en Uriondo.','Provincia clave para experiencias vitivinicolas y paisajes altoandinos.','Jose Maria Aviles reune el valle de Uriondo, bodegas, vinedos, singani y paisajes de altura hacia Yunchara. Es una provincia ideal para turismo gastronomico, fotografico y de naturaleza.','municipios/01KY0KVDES1CDHM4R2RYSA68RR.JPG','[\"municipios/galeria/01KY0KVDF0DEA5PW0520YZ8W07.JPG\", \"municipios/galeria/01KY0KVDF36ED5Z2HJ318MNYJA.JPG\", \"municipios/galeria/01KY0KVDF8S9194SS3XDVYRK5G.JPG\", \"municipios/galeria/01KY0KVDFE55JHB8BD1BB1X30C.JPG\", \"municipios/galeria/01KY0KVDFN1JBG1ZDQMYPDN7HE.jpg\"]',NULL,'Ruta del Vino\nValle de la Concepcion\nBodegas y vinedos\nPaisajes altoandinos\nLagunas y rutas naturales','Vendimia chapaca\nExperiencias de degustacion\nFerias productivas locales','Coordinar visitas a bodegas con anticipacion\nLlevar abrigo para zonas altas\nCombinar gastronomia local con recorridos fotograficos',3,1,'2026-07-21 00:19:35','2026-07-21 00:35:33');
