INSERT INTO `destinos` (`id`, `categoria_id`, `municipio_id`, `nombre`, `subtitulo`, `slug`, `resumen`, `introduccion`, `descripcion`, `como_llegar`, `rutas_llegada`, `mejor_epoca`, `duracion_recomendada`, `recomendaciones`, `imagen`, `imagenes_secundarias`, `ubicacion`, `precio`, `latitud`, `longitud`, `destacado`, `activo`, `orden`, `created_at`, `updated_at`) VALUES (4,3,10,'Casa Vieja',NULL,'casa-vieja','Historia, arquitectura tradicional y cultura viva de San Lorenzo.',NULL,'Casa Vieja es una referencia patrimonial para conocer la vida tradicional tarijena, sus patios, arquitectura y memoria cultural.',NULL,'[]',NULL,NULL,NULL,'destinos/01KYTGC63YJ0FSW5TRGXE1513P.webp','[]','San Lorenzo',NULL,NULL,NULL,1,1,2,'2026-07-11 04:20:57','2026-07-30 21:55:03');
INSERT INTO `destinos` (`id`, `categoria_id`, `municipio_id`, `nombre`, `subtitulo`, `slug`, `resumen`, `introduccion`, `descripcion`, `como_llegar`, `rutas_llegada`, `mejor_epoca`, `duracion_recomendada`, `recomendaciones`, `imagen`, `imagenes_secundarias`, `ubicacion`, `precio`, `latitud`, `longitud`, `destacado`, `activo`, `orden`, `created_at`, `updated_at`) VALUES (5,1,9,'Reserva Biologica Cordillera de Sama',NULL,'reserva-biologica-cordillera-de-sama','Lagunas altoandinas, miradores, rutas naturales y paisajes de altura.',NULL,'La Reserva Biologica Cordillera de Sama protege ecosistemas altoandinos, lagunas, biodiversidad y paisajes ideales para turismo de naturaleza.',NULL,'[]',NULL,NULL,NULL,'destinos/01KYTGKYZ87DN5G0MMJ4A37J44.jpg','[]','Yunchara y Padcaya',NULL,NULL,NULL,1,1,3,'2026-07-11 04:20:57','2026-07-30 21:59:18');
INSERT INTO `destinos` (`id`, `categoria_id`, `municipio_id`, `nombre`, `subtitulo`, `slug`, `resumen`, `introduccion`, `descripcion`, `como_llegar`, `rutas_llegada`, `mejor_epoca`, `duracion_recomendada`, `recomendaciones`, `imagen`, `imagenes_secundarias`, `ubicacion`, `precio`, `latitud`, `longitud`, `destacado`, `activo`, `orden`, `created_at`, `updated_at`) VALUES (6,1,9,'Laguna Brava','Una travesía de altura entre cumbres, roca y espejos de agua.','laguna-brava','Laguna altoandina situada entre las cumbres del cerro Campanario, rodeada de picos ocres, riberas rocosas y paisajes extremos de la Cordillera de Sama.','Una aventura de alta montaña hacia uno de los paisajes más remotos y sorprendentes de Tarija.','Laguna Brava se encuentra entre las cumbres del cerro Campanario, en la Reserva Biológica Cordillera de Sama. A unos 4.300 metros sobre el nivel del mar, el recorrido atraviesa un paisaje altoandino de roca, viento y grandes horizontes.\n\nLa laguna está rodeada por picos de tonos morados y ocres, riberas abruptas y formaciones rocosas de probable origen volcánico. En sus alrededores aparecen otras lagunas pequeñas con distintas tonalidades, creando un escenario especialmente atractivo para el senderismo, la fotografía de naturaleza y la contemplación.\n\nLa experiencia exige preparación física, planificación y respeto por las normas del área protegida. Una ruta de senderismo publicada desde las cercanías de Yuticancha registra 10,44 kilómetros, dificultad moderada, 533 metros de desnivel positivo y una duración total cercana a seis horas.','El acceso turístico se organiza desde la ciudad de Tarija hacia la zona alta de Yunchará y la comunidad de Yuticancha. El último tramo corresponde a un trekking de altura y debe planificarse con guía u operador conocedor de la Reserva Biológica Cordillera de Sama. Los puntos del mapa son referencias para probar el recorrido; confirma las coordenadas oficiales y el punto exacto de inicio antes de viajar.','[{\"nombre\": \"Desde Tarija\", \"origen\": \"Ciudad de Tarija\", \"tramos\": [{\"desde\": \"Ciudad de Tarija\", \"hasta\": \"Zona alta de Yunchará\", \"medio\": \"auto\", \"latitud\": -21.7936, \"duracion\": \"Duración variable\", \"longitud\": -65.165, \"indicaciones\": \"Se recomienda vehículo adecuado y coordinación previa con un guía local.\"}, {\"desde\": \"Zona alta de Yunchará\", \"hasta\": \"Yuticancha\", \"medio\": \"auto\", \"latitud\": -21.91549, \"duracion\": \"Consultar acceso\", \"longitud\": -65.06537, \"indicaciones\": \"Punto de referencia para iniciar la experiencia de senderismo.\"}, {\"desde\": \"Yuticancha\", \"hasta\": \"Laguna Brava\", \"medio\": \"caminata\", \"latitud\": -21.883, \"duracion\": \"5 h 55 min circuito\", \"longitud\": -65.112, \"indicaciones\": \"Ruta circular de 10,44 km, dificultad moderada y gran altitud. Realizar con guía.\"}], \"descripcion\": \"Alternativa de referencia desde la ciudad de Tarija hasta el acceso por Yuticancha y posterior trekking de altura.\", \"origen_latitud\": -21.53549, \"origen_longitud\": -64.72956}, {\"nombre\": \"Desde Yuticancha\", \"origen\": \"Comunidad de Yuticancha\", \"tramos\": [{\"desde\": \"Yuticancha\", \"hasta\": \"Laguna Brava\", \"medio\": \"caminata\", \"latitud\": -21.883, \"duracion\": \"5 h 55 min circuito\", \"longitud\": -65.112, \"indicaciones\": \"10,44 km, desnivel positivo de 533 m y altitud máxima reportada de 4.327 m.\"}], \"descripcion\": \"Opción para visitantes que ya se encuentran en la zona alta y han coordinado guía, permisos y logística.\", \"origen_latitud\": -21.91549, \"origen_longitud\": -65.06537}]','Época seca, aproximadamente de abril a noviembre, siempre sujeta al clima y al estado del acceso','Jornada completa; el circuito de trekking puede tomar cerca de 6 horas','Realiza la visita con guía u operador que conozca la Reserva Biológica Cordillera de Sama.\nAclimátate previamente: el recorrido supera los 4.300 metros de altitud.\nLleva ropa térmica por capas, cortaviento, gorra, guantes y calzado de trekking.\nUsa protector solar, gafas con filtro UV y lleva suficiente agua y alimentos energéticos.\nVerifica el clima, el estado del camino y las autorizaciones antes de salir.\nNo abandones residuos ni te apartes de los senderos habilitados.\nDescarga el mapa o la ruta para consultarla sin conexión.','destinos/01KYBBK7KYFDQWT1S60FNENWXT.jpeg','[\"destinos/galeria/01KYBBY2WH4CTWACKNXVTKRR85.jpeg\", \"destinos/galeria/01KYBBY2WN0N5AZMNRH3VYAY6X.jpeg\", \"destinos/galeria/01KYBBY2WRG6NEYMRZ1ATER1H3.jpeg\", \"destinos/galeria/01KYBBY2WV852Y8QRKE5WEZ8W1.jpeg\", \"destinos/galeria/01KYBBY2WY7S2RQ26EDN95ZGEP.jpeg\", \"destinos/galeria/01KYBBY2X2Z96D71KVXZ4YV6TC.jpeg\", \"destinos/galeria/01KYBBY2X5BJHTVGA5CSN4YE7D.jpeg\", \"destinos/galeria/01KYBBY2X898EYBT161K1WEB93.jpeg\", \"destinos/galeria/01KYBBY2XBF3CEM15FBW5Q5DS6.jpeg\"]','Zona alta de Yuticancha, Reserva Biológica Cordillera de Sama',NULL,-21.8830000,-65.1120000,1,1,0,'2026-07-25 00:42:55','2026-07-30 19:15:42');
