INSERT INTO `weekly_activities` (`id`, `municipio_id`, `titulo`, `slug`, `subtitulo`, `descripcion`, `contenido`, `imagen`, `galeria`, `video`, `lugar`, `fecha_actividad`, `visible_desde`, `visible_hasta`, `texto_boton`, `enlace`, `orden`, `activo`, `created_at`, `updated_at`, `sectores_interes`, `horarios`, `direccion`, `mapa_url`, `telefono`, `whatsapp`, `correo`, `sitio_web`, `facebook`, `instagram`, `x_url`, `youtube_url`) VALUES (1,7,'Descubre las actividades de esta semana','descubre-las-actividades-de-esta-semana','Agenda turística de Tarija','Consulta las experiencias, eventos y recorridos preparados para disfrutar Tarija esta semana. Este anuncio puede editarse o reemplazarse desde el panel administrativo.',NULL,'actividades-semana/01KXNKXRSXXCRV8YGAD0YCQY0W.jpg','[\"actividades-semana/galeria/01KXNN51SJTWN85W585HB0KK99.jpg\", \"actividades-semana/galeria/01KXNN51SNVGW34AVSM3XH6N1S.jpg\", \"actividades-semana/galeria/01KXNN51SP4HV8PJ408EZT1J7C.png\", \"actividades-semana/galeria/01KXNN51SRY32WYTQTTNSGS6Z1.jpg\", \"actividades-semana/galeria/01KXNN51STW6PT6XXMMBS1YADY.jpeg\"]','actividades-semana/videos/01KYQ2CVDQE3QF3M33TYDXYYPH.mp4',NULL,NULL,NULL,NULL,'Ver agenda turística','/eventos',1,1,'2026-07-13 19:56:53','2026-07-29 13:53:01','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO `weekly_activities` (`id`, `municipio_id`, `titulo`, `slug`, `subtitulo`, `descripcion`, `contenido`, `imagen`, `galeria`, `video`, `lugar`, `fecha_actividad`, `visible_desde`, `visible_hasta`, `texto_boton`, `enlace`, `orden`, `activo`, `created_at`, `updated_at`, `sectores_interes`, `horarios`, `direccion`, `mapa_url`, `telefono`, `whatsapp`, `correo`, `sitio_web`, `facebook`, `instagram`, `x_url`, `youtube_url`) VALUES (2,NULL,'Descubre las actividades de esta semana','descubre-las-actividades-de-esta-semana-1','Agenda turística de Tarija',NULL,NULL,NULL,'[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2,1,'2026-07-16 18:49:11','2026-07-16 18:49:11','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO `eventos` (`id`, `destino_id`, `municipio_id`, `titulo`, `slug`, `descripcion`, `imagen`, `lugar`, `fecha_inicio`, `fecha_fin`, `activo`, `created_at`, `updated_at`) VALUES (2,NULL,7,'Fiesta Grande de San Roque','fiesta-grande-de-san-roque','Celebración religiosa y cultural en honor a San Roque, reconocida por la UNESCO como Patrimonio Cultural Inmaterial de la Humanidad. Durante agosto y septiembre, miles de promesantes chunchos, músicos y devotos recorren las calles de Tarija entre procesiones, danzas, plegarias, gastronomía tradicional y expresiones de fe. La celebración mantiene la tradición de abstinencia de bebidas alcohólicas y tiene como punto central la Iglesia de San Roque.','/images/eventos/fiesta-grande-san-roque.webp','Iglesia de San Roque y calles del centro histórico de Tarija','2026-08-15 08:00:00','2026-09-12 22:00:00',1,'2026-07-30 22:09:41','2026-07-30 22:09:41');
INSERT INTO `eventos` (`id`, `destino_id`, `municipio_id`, `titulo`, `slug`, `descripcion`, `imagen`, `lugar`, `fecha_inicio`, `fecha_fin`, `activo`, `created_at`, `updated_at`) VALUES (3,NULL,12,'Peregrinación al Santuario de la Virgen de Chaguaya','peregrinacion-al-santuario-de-la-virgen-de-chaguaya','Una de las manifestaciones de fe más importantes del sur de Bolivia. Peregrinos de Tarija y otras regiones recorren a pie el camino hasta el Santuario de la Virgen de Chaguaya para agradecer, cumplir promesas y participar en las celebraciones religiosas. La temporada se extiende durante un mes y reúne caminatas, misas, procesiones y tradiciones comunitarias.','/images/eventos/peregrinacion-chaguaya.jpg','Santuario de la Virgen de Chaguaya, comunidad de Chaguaya, municipio de Padcaya','2026-08-15 06:00:00','2026-09-14 18:00:00',1,'2026-07-30 22:09:41','2026-07-30 22:09:41');
INSERT INTO `noticias` (`id`, `destino_id`, `titulo`, `slug`, `resumen`, `contenido`, `fuente_nombre`, `fuente_url`, `imagen`, `publicado_en`, `activo`, `newsletter_enviado_en`, `newsletter_destinatarios`, `newsletter_fallidos`, `created_at`, `updated_at`) VALUES (2,NULL,'Actualidad de la Gobernación de Tarija','actualidad-de-la-gobernacion-de-tarija','Conoce la información y las actividades compartidas por la Gobernación de Tarija a través de sus canales oficiales.','Esta publicación institucional fue incorporada al portal turístico como contenido de prueba. Puedes consultar la información completa desde el enlace original de Facebook. El título, resumen, contenido, fotografía, fecha y fuente pueden actualizarse posteriormente desde el panel administrativo.','Gobernación de Tarija','https://www.facebook.com/share/19JcPcjJMT/?mibextid=wwXIfr','identidad/01KX4DBRY2PYS7W7SJHBV2D02H.png','2026-07-30 18:17:37',1,NULL,0,0,'2026-07-30 22:17:37','2026-07-30 22:18:03');
